Trading daily from Steenberg Village in Tokai, Rock Thai Sushi Steenberg suits diners across the southern suburbs looking for a casual Thai and sushi meal, whether dining in, taking away, or having it delivered.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://za.africabz.com/western-cape/rock-thai-sushi-415507', '$[#]', 'https://www.dining-out.co.za/md/Rock-Thai-Sushi-Steenberg/10886'), description_enriched_at = datetime('now') WHERE slug = 'rock-thai-sushi-steenberg-tokai' AND description = 'Rock Thai Sushi Steenberg serves Thai, seafood, sushi and vegetarian dishes from a shopfront in Steenberg Village, Tokai.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
